using Microsoft.AspNetCore.Mvc;
public abstract class BaseController:Controller { protected bool SignedIn=>HttpContext.Session.GetInt32("UserId").HasValue; protected string Role=>HttpContext.Session.GetString("Role")??""; protected IActionResult Require(string role){if(!SignedIn)return RedirectToAction("Login","Account");if(Role!=role)return RedirectToAction("Index","Home");return null!;} protected void SetUser(UserDto u){HttpContext.Session.SetInt32("UserId",u.UserId);HttpContext.Session.SetString("Role",u.Role);HttpContext.Session.SetString("FullName",u.FullName);HttpContext.Session.SetString("Email",u.Email);} }
